import Testing
import DartCore
import DartGames
import DartTestSupport

/// Cross-check of Killer against the Python reference that computed the vectors of GAMES.md: 120 random journals
/// over the four levels, 2 to 8 players, every option, with early confirmations, self-hits and round limits.
/// For each journal the reference recorded a hash of the state after every input (zones, lives, arming progress,
/// kills, eliminations, ranks, phase, current player, round), a hash of every event of every input, and the final
/// state. 60 of the 68 expert games run past round 1, so their redraws are part of what is compared.
@Suite struct KillerOracleTests {
    private let registry = GameRegistry.standard

    /// "T-|0|3|2|15.2,1,2,3,0/9.12,0,0,0,1|1.2": turn state, one row "zone,lives,armingProgress,kills,eliminated"
    /// per player, ranks.
    private func state(_ match: GameMatch) -> String {
        let zones = match.killerZones
        let lives = match.killerInts("lives")
        let arming = match.killerInts("armingProgress")
        let kills = match.killerInts("kills")
        let eliminated = match.killerBools("eliminated")
        let rows = zones.indices.map { player in
            "\(zones[player].map(String.init).joined(separator: ".")),\(lives[player]),\(arming[player]),\(kills[player]),\(eliminated[player] ? 1 : 0)"
        }
        return "\(KillerTestOracle.turnState(match))|\(rows.joined(separator: "/"))|\(KillerTestOracle.ranks(match))"
    }

    private func describe(_ events: [GameEvent]) -> String {
        events.map { event in
            switch event {
            case .dartRegistered(let player, let hit): return "d\(player).\(hit.notation)"
            case .noEffect(let player): return "n\(player)"
            case .armingHit(let player, let progress): return "a\(player).\(progress)"
            case .becameKiller(let player): return "k\(player)"
            case .lifeLost(let player, let by, let livesLeft): return "l\(player).\(by).\(livesLeft)"
            case .playerEliminated(let player, let by): return "e\(player).\(by)"
            case .zoneChanged(let player, let zone): return "z\(player).\(zone.map(String.init).joined(separator: "."))"
            case .turnCompleted(let player): return "c\(player)"
            case .roundStarted(let round): return "r\(round)"
            case .turnStarted(let player, let round): return "t\(player).\(round)"
            case .gameFinished(let reason): return "f\(KillerTestOracle.reason(reason))"
            default: return "unexpected(\(event))"
            }
        }.joined(separator: ",")
    }

    @Test func referenceJournals_sameStatesAndSameEventsAfterEveryInput() throws {
        let lines = Self.journals.split(separator: "\n")
        #expect(lines.count == 120)
        var levels: [String: Int] = [:]
        for (index, line) in lines.enumerated() {
            let fields = line.split(separator: ";", omittingEmptySubsequences: false).map(String.init)
            try #require(fields.count == 11, "line \(index)")
            let seed = try #require(UInt64(fields[0]))
            let players = try #require(Int(fields[1]))
            let options: GameOptions = [
                "level": .string(fields[2]),
                "lives": .int(try #require(Int(fields[3]))),
                "armingHits": .int(try #require(Int(fields[4]))),
                "selfHitPenalty": .bool(fields[5] == "1"),
                "maxRounds": fields[6] == "-" ? .null : .int(try #require(Int(fields[6]))),
            ]
            levels[fields[2], default: 0] += 1
            var match = try registry.match(.killer, options, players: players, seed: seed)
            var states = KillerTestOracle.emptyHash
            var events = KillerTestOracle.emptyHash
            for input in try KillerTestOracle.inputs(fields[7]) {
                let outcome = match.killerApply(input)
                #expect(outcome.isAccepted, "line \(index): the reference only recorded accepted inputs")
                KillerTestOracle.mix(&states, state(match) + ";")
                KillerTestOracle.mix(&events, describe(outcome.events) + ";")
            }
            #expect(state(match) == fields[10], "line \(index): final state")
            #expect(String(states, radix: 16) == fields[8].drop { $0 == "0" }, "line \(index): a state differs on the way")
            #expect(String(events, radix: 16) == fields[9].drop { $0 == "0" }, "line \(index): an event differs on the way")
            #expect(try registry.restoreMatch(match.record).snapshot == match.snapshot, "line \(index)")
        }
        #expect(levels == ["easy": 19, "medium": 15, "hard": 18, "expert": 68])
    }

